import os
from openpyxl import load_workbook

print("--- Files in workspace ---")
for root, dirs, files in os.walk('.'):
    if '.codex' in root:
        continue
    depth = root.count(os.sep)
    indent = '  ' * depth
    print(f"{indent}{root}/")
    for f in files:
        print(f"{indent}  {f}")

target = 'budget.xlsx'
print(f"\n--- Loading {target} ---")
wb = load_workbook(target, data_only=False)
print("Sheets:", wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f"\n=== Sheet: {name} (dims: {ws.dimensions}, max_row={ws.max_row}, max_col={ws.max_column}) ===")
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is not None:
                print(f"{cell.coordinate}: {cell.value!r}")

import importlib, sys
print("Python:", sys.version)
for mod in ["openpyxl", "pandas", "xlsxwriter", "xlrd", "numpy", "odf", "pyxlsb"]:
    try:
        m = importlib.import_module(mod)
        print(f"{mod}: AVAILABLE ({getattr(m, '__version__', '?')})")
    except ImportError:
        print(f"{mod}: missing")

import zipfile, re
import xml.etree.ElementTree as ET

M = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
R = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'

def q(tag):
    return f'{{{M}}}{tag}'

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    col = 0
    for ch in m.group(1):
        col = col * 26 + (ord(ch) - 64)
    return int(m.group(2)), col

def cell_text(cell):
    for child in cell:
        if child.tag == q('v'):
            return child.text
        if child.tag == q('is'):
            return ''.join(t.text or '' for t in child.iter(q('t')))
    return None

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("--- Zip contents ---")
    for n in names:
        print(" ", n)

    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = [(s.get('name'), s.get(f'{{{R}}}id')) for s in wb_root.iter(q('sheet'))]
    print("\n--- Sheets ---")
    print(sheets)

    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_targets = {r.get('Id'): r.get('Target') for r in rels_root}
    print("\n--- Workbook rels ---")
    print(rel_targets)

    ss = []
    if 'xl/sharedStrings.xml' in names:
        ss_root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        ss = [''.join(t.text or '' for t in si.iter(q('t'))) for si in ss_root.iter(q('si'))]
        print(f"\n--- Shared strings ({len(ss)}) ---")
        for i, s in enumerate(ss):
            print(f"  [{i}] {s!r}")

    for name, rid in sheets:
        target = rel_targets.get(rid)
        path = target if target.startswith('xl/') else 'xl/' + target
        sheet_root = ET.fromstring(z.read(path))
        print(f"\n=== Sheet: {name} (file: {path}) ===")
        for row in sheet_root.iter(q('row')):
            for cell in row.iter(q('c')):
                ref = cell.get('r')
                if ref is None:
                    continue
                t = cell.get('t')
                raw = cell_text(cell)
                if raw is None:
                    continue
                if t == 's':
                    val = ss[int(raw)]
                elif t == 'inlineStr':
                    val = cell_text(cell)
                elif t == 'b':
                    val = raw == '1'
                elif t == 'str':
                    val = raw
                else:
                    try:
                        val = float(raw) if '.' in raw or 'e' in raw.lower() else int(raw)
                    except (TypeError, ValueError):
                        val = raw
                f = cell.find(q('f'))
                fstr = ('=' + (f.text or '')) if f is not None else ''
                print(f"  {ref}: {val!r} {fstr}".rstrip())

