with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_targets = {r.get('Id'): r.get('Target') for r in rels_root}
    sheet_root = ET.fromstring(z.read(rel_targets['rId1'].lstrip('/')))
    ss = []
    if 'xl/sharedStrings.xml' in names:
        ss_root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        ss = [''.join(t.text or '' for t in si.iter(q('t'))) for si in ss_root.iter(q('si'))]

def val(cell):
    t = cell.get('t')
    raw = cell_text(cell)
    if raw is None:
        return None
    if t == 's':
        return ss[int(raw)]
    if t == 'b':
        return raw == '1'
    try:
        return float(raw) if ('.' in raw or 'e' in raw.lower()) else int(raw)
    except (TypeError, ValueError):
        return raw

# Collect expenses: rows where column C is numeric and A is a category label
expenses = []
for row in sheet_root.iter(q('row')):
    cells = {c.get('r'): c for c in row.iter(q('c')) if c.get('r')}
    c_cell = cells.get(f"{row.get('r') and 'C'}{row.get('r')}")
    a_cell = cells.get(f"{row.get('r') and 'A'}{row.get('r')}")
    if c_cell is None:
        continue
    amount = val(c_cell)
    if not isinstance(amount, (int, float)):
        continue
    cat = val(a_cell) if a_cell is not None else None
    expenses.append((cat, amount))

from collections import OrderedDict
per_cat = OrderedDict()
total = 0
for cat, amount in expenses:
    per_cat[cat] = per_cat.get(cat, 0) + amount
    total += amount

print("Expense line items:")
for cat, amount in expenses:
    print(f"  {cat}: {amount}")
print("\nPer-category totals:")
for cat, subtotal in per_cat.items():
    print(f"  {cat}: {subtotal}")
print(f"\nTOTAL EXPENSES: {total}")

